}
function decideFallbackAction(isRetryable, inFallbackChain) {
  if (isRetryable && !inFallbackChain)
    return "native-retry";
  if (isRetryable && inFallbackChain)
    return "stay-pinned";
  if (!isRetryable && !inFallbackChain)
    return "swap-and-pin";
